+const VERSION_RE = new RegExp(
+  `^v?(\\d+)\\.(\\d+)\\.(\\d+)(?:-(${IDENT}(?:\\.${IDENT})*))?(?:\\+(${IDENT}(?:\\.${IDENT})*))?$`,
+);
+const NUMERIC_RE = /^\d+$/;
